  code:i.json.code||'8000', naam:i.json.naam||'Omzet NL',
  aantal:parseInt(i.json.aantal||0),
  totaal_excl:parseFloat(i.json.totaal_excl||0),
  totaal_btw:parseFloat(i.json.totaal_btw||0),
  totaal_incl:parseFloat(i.json.totaal_incl||0)
}));
return [{json:{...parse,_omzetRows:omzetRows}}];

function fmt(v){return '€ '+parseFloat(v||0).toLocaleString('nl-NL',{minimumFractionDigits:2,maximumFractionDigits:2});}
